from typing import List


def parse_nested_parens(paren_string: str) -> List[int]:
    stack = []
    result = []

    for char in paren_string:
        if char == '(':
            stack.append(char)
        elif char == ')' and stack:
            depth = 0
            while stack:
                last_char = stack.pop()
                if last_char == '(':
                    depth += 1
            result.append(depth)

    return result


