def fib(n: int):
    if n <= 0:
        raise ValueError("Input must be a positive integer")
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        # Calculate the n-th Fibonacci number using Binet's formula
        # Phi is the golden ratio minus 1, which is (1 + sqrt(5)) / 2
        phi = (1 + math.sqrt(5)) / 2
        fib_n = round((phi**n - (1 - phi)**n) / math.sqrt(5))
        return fib_n

