import collections


def histogram(test):
    """
    Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    :param test: A string of lowercase letters separated by spaces.
    :return: A dictionary of the most repetitive letter(s) and their counts.

    Example:
    >>> histogram('a b c')
    {'a': 1, 'b': 1, 'c': 1}
    >>> histogram('a b b a')
    {'a': 2, 'b': 2}
    >>> histogram('a b c a b')
    {'a': 2, 'b': 2}
    >>> histogram('b b b b a')
    {'b': 4}
    >>> histogram('')
    {}
    """

    if not test:
        return {}

    test = test.split()
    counts = collections.Counter(test)
    max_count = max(counts.values(), default=0)
    most_repetitive_letters = {letter: count for letter, count in counts.items() if count == max_count}

    return most_repetitive_letters

