import heapq


def minPath(grid, k):
    N = len(grid)
    heap = []
    visited = set()
    path = []

    def dfs(x, y, cur_path):
        cur_path.append(grid[x][y])
        if len(cur_path) == k:
            if (x, y) not in visited:
                heapq.heappush(heap, (sum(cur_path), cur_path[:]))
            return True
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N and (nx, ny) not in visited:
                if dfs(nx, ny, cur_path):
                    return True
        visited.add((x, y))
        cur_path.pop()
        return False

    for i in range(N):
        for j in range(N):
            dfs(i, j, [])

    while heap:
        path = heapq.heappop(heap)
        if path:
            return path[1]

    return []

